function t(k){return I18N[currentLang]?.[k]||I18N.en[k]||k}
function setLanguage(lang){currentLang=lang==='en'?'en':'vi';localStorage.setItem('free-lang',currentLang);document.documentElement.lang=currentLang;document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>el.placeholder=t(el.dataset.i18nPlaceholder));$('#langVI')?.classList.toggle('active',currentLang==='vi');$('#langEN')?.classList.toggle('active',currentLang==='en');renderContacts();renderChat();renderBlocked();renderDeviceList();if(me&&profile)renderIdentity();updateStorageText();updateRecoverySecretToggle()}

function updateRecoverySecretToggle(){const b=$('#toggleRecoverySecret'),f=$('#accountRecoverySecret');if(!b||!f)return;b.textContent=f.type==='password'?t('show'):t('hide')}
function pq(){if(!globalThis.FREEPQ)throw new Error('Post-quantum runtime unavailable.');return globalThis.FREEPQ}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open(dbName,1);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains('kv'))d.createObjectStore('kv')};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function getKV(key){return new Promise((res,rej)=>{const r=db.transaction('kv').objectStore('kv').get(key);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function setKV(key,val){return new Promise((res,rej)=>{const r=db.transaction('kv','readwrite').objectStore('kv').put(val,key);r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
function delKV(key){return new Promise((res,rej)=>{const r=db.transaction('kv','readwrite').objectStore('kv').delete(key);r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
async function sha512(data){return new Uint8Array(await crypto.subtle.digest('SHA-512',data))}
async function identityId(kemPub,sigPub){return hex((await sha512(enc.encode(`${CRYPTO_SUITE}:${kemPub}:${sigPub}`))).slice(0,32))}
const B32='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
function base32(bytes){let bits=0,value=0,out='';for(const byte of bytes){value=(value<<8)|byte;bits+=8;while(bits>=5){out+=B32[(value>>>(bits-5))&31];bits-=5}}if(bits)out+=B32[(value<<(5-bits))&31];return out}
async function shortIdFor(id){const d=await sha512(enc.encode(`FREE-SHORT:${id}`));const body=base32(d.slice(0,7)).slice(0,10),check=base32(d.slice(7,9)).slice(0,2);return `${body.slice(0,5)}-${body.slice(5)}-${check}`}
async function createIdentity(){
 const existing=await getKV('identity');
 if(existing && existing.cryptoSuite!==CRYPTO_SUITE){await setKV('identity-classical-archive',existing);await setKV('contacts-classical-archive',await getKV('contacts')||{});await setKV('chats-classical-archive',await getKV('chats')||{});await setKV('contacts',{});await setKV('chats',{})}
 const kem=pq().kemKeygen(),sig=pq().sigKeygen();const id=await identityId(kem.publicKey,sig.publicKey),shortId=await shortIdFor(id);
 const raw={v:2,cryptoSuite:CRYPTO_SUITE,kem:KEM_NAME,signature:SIG_NAME,id,shortId,kemPublicKey:kem.publicKey,kemSecretKey:kem.secretKey,sigPublicKey:sig.publicKey,sigSecretKey:sig.secretKey,createdAt:Date.now()};
 await setKV('identity',raw);return{...raw,raw}
}
function wrapIdentity(raw){return raw?{...raw,raw}:null}
function cardForMe(){return{v:2,cryptoSuite:CRYPTO_SUITE,kem:KEM_NAME,signature:SIG_NAME,id:me.id,shortId:me.shortId,displayName:profile?.displayName||'',kemPublicKey:me.kemPublicKey,sigPublicKey:me.sigPublicKey}}
async function validateCard(card){if(!card||card.v!==2||card.cryptoSuite!==CRYPTO_SUITE||card.kem!==KEM_NAME||card.signature!==SIG_NAME||!card.id||!card.kemPublicKey||!card.sigPublicKey)return false;return await identityId(card.kemPublicKey,card.sigPublicKey)===card.id}
async function signObject(obj){return pq().sign(enc.encode(JSON.stringify(obj)),me.sigSecretKey)}
async function verifyObject(obj,signature,sigPublicKey){try{return pq().verify(signature,enc.encode(JSON.stringify(obj)),sigPublicKey)}catch{return false}}
async function messageKey(sharedSecret,from,to,msgId){const base=await crypto.subtle.importKey('raw',unb64(sharedSecret),'HKDF',false,['deriveKey']);return crypto.subtle.deriveKey({name:'HKDF',hash:'SHA-512',salt:enc.encode('FREE-PQ1-MESSAGE'),info:enc.encode(`${from}:${to}:${msgId}`)},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
function aadFor(from,to,msgId,sentAt,kemCiphertext){return enc.encode(JSON.stringify({suite:CRYPTO_SUITE,from,to,msgId,sentAt,kemCiphertext}))}
async function saveLocalSafetySnapshot(){if(!me?.id)return;try{await setKV(`state-safety:${me.id}`,{accountId:me.id,profile,contacts,chats,blockedIds,savedAt:Date.now()})}catch(e){console.warn('local safety snapshot failed',e)}}
async function restoreLocalSafetySnapshot(){if(!me?.id)return;try{const snap=await getKV(`state-safety:${me.id}`);if(!snap||snap.accountId!==me.id)return;const currentCount=Object.values(chats||{}).reduce((n,a)=>n+(Array.isArray(a)?a.length:0),0),snapCount=Object.values(snap.chats||{}).reduce((n,a)=>n+(Array.isArray(a)?a.length:0),0);if(snapCount>currentCount){contacts={...(snap.contacts||{}),...contacts};chats=mergeChats(snap.chats||{},chats);blockedIds={...(snap.blockedIds||{}),...blockedIds};await setKV('contacts',contacts);await setKV('chats',chats);await setKV('blockedIds',blockedIds)}}catch(e){console.warn('local safety restore failed',e)}}
async function saveState(){await setKV('contacts',contacts);await setKV('chats',chats);await setKV('blockedIds',blockedIds);await setKV('storageEnabled',storageEnabled);await setKV('readReceiptsEnabled',readReceiptsEnabled);await setKV('appLockEnabled',appLockEnabled);await saveLocalSafetySnapshot();scheduleVaultSync();scheduleArchiveSync()}

function mergeChats(a={},b={}){const out={};for(const id of new Set([...Object.keys(a||{}),...Object.keys(b||{})])){const by=new Map();for(const m of [...(a[id]||[]),...(b[id]||[])]){if(!m?.msgId)continue;const prev=by.get(m.msgId)||{};by.set(m.msgId,{...prev,...m,status:(prev.status==='read'||m.status==='read')?'read':(prev.status==='delivered'||m.status==='delivered')?'delivered':m.status||prev.status})}out[id]=[...by.values()].sort((x,y)=>(x.sentAt||0)-(y.sentAt||0)).slice(-5000)}return out}
function mergeAccountState(remote={}){contacts={...(remote.contacts||{}),...contacts};chats=mergeChats(remote.chats||{},chats);blockedIds={...(remote.blockedIds||{}),...blockedIds}}
async function deriveVaultSyncKey(){const secretText=await getKV('recoverySecret');if(!secretText||!me?.sigSecretKey)return null;const secret=unbase32(secretText),priv=unb64(me.sigSecretKey);const material=new Uint8Array(secret.length+priv.length);material.set(secret);material.set(priv,secret.length);const digest=await crypto.subtle.digest('SHA-512',material);return crypto.subtle.importKey('raw',digest,'AES-GCM',false,['encrypt','decrypt'])}
async function encryptVaultState(revision){const key=await deriveVaultSyncKey();if(!key)return null;const address=await getKV('recoveryAddress');if(!address)return null;const iv=crypto.getRandomValues(new Uint8Array(12));const payload={format:'FREE-VAULT-SYNC-1',accountId:me.id,profile,contacts,chats,blockedIds,revision,updatedAt:Date.now()};const ct=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,enc.encode(JSON.stringify(payload))));return{address,iv:b64url(iv),ciphertext:b64url(ct)}}
async function decryptVaultState(blob){const key=await deriveVaultSyncKey();if(!key)return null;try{const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64url(blob.iv)},key,unb64url(blob.ciphertext));const state=JSON.parse(dec.decode(plain));if(state.format!=='FREE-VAULT-SYNC-1'||state.accountId!==me.id)throw new Error('vault identity mismatch');return state}catch(e){console.warn('vault sync decrypt failed',e);return null}}
async function fetchRemoteVault(){const address=await getKV('recoveryAddress');if(!address)return null;const r=await fetch('/api/account-vault?address='+encodeURIComponent(address),{cache:'no-store'});if(r.status===404)return null;if(!r.ok)throw new Error('Vault sync fetch failed');return r.json()}
async function pushVaultState(){if(vaultSyncBusy||!vaultHydrated||!me||ws?.readyState!==1)return;const address=await getKV('recoveryAddress'),secret=await getKV('recoverySecret');if(!address||!secret)return;vaultSyncBusy=true;try{let remote=null;try{remote=await fetchRemoteVault()}catch(e){console.warn('vault preflight fetch failed',e);return}if(remote){const state=await decryptVaultState(remote);if(!state){console.warn('remote vault exists but cannot be decrypted; refusing overwrite');return}mergeAccountState(state);vaultRevision=Math.max(vaultRevision,Number(remote.revision)||0);await setKV('contacts',contacts);await setKV('chats',chats);await setKV('blockedIds',blockedIds);await saveLocalSafetySnapshot();renderContacts();renderChat();renderBlocked()}const revision=Math.max(Date.now(),vaultRevision+1);const encVault=await encryptVaultState(revision);if(!encVault)return;const digestHex=hex(await crypto.subtle.digest('SHA-512',enc.encode(encVault.ciphertext)));const bytes=enc.encode(`FREE-ACCOUNT-VAULT-1:${encVault.address}:${revision}:${digestHex}`);const signature=await Promise.resolve(pq().sign(bytes,me.sigSecretKey));const body={v:1,suite:CRYPTO_SUITE,address:encVault.address,accountId:me.id,revision,iv:encVault.iv,ciphertext:encVault.ciphertext,signature};const r=await fetch('/api/account-vault?address='+encodeURIComponent(encVault.address),{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(body)});if(r.ok)vaultRevision=revision;else console.warn('vault sync rejected',r.status)}catch(e){console.warn('vault sync push failed',e)}finally{vaultSyncBusy=false}}
function scheduleVaultSync(){clearTimeout(vaultSyncTimer);vaultSyncTimer=setTimeout(()=>pushVaultState(),700)}
async function pullVaultState(){if(!me)return;try{const remote=await fetchRemoteVault();if(remote){const state=await decryptVaultState(remote);if(!state)throw new Error('Remote vault could not be decrypted');mergeAccountState(state);vaultRevision=Math.max(vaultRevision,Number(remote.revision)||0);await setKV('contacts',contacts);await setKV('chats',chats);await setKV('blockedIds',blockedIds);await saveLocalSafetySnapshot();renderContacts();renderChat();renderBlocked()}vaultHydrated=true}catch(e){vaultHydrated=false;throw e}}


// ---- FREE Distributed Storage v1: encrypted, content-addressed message archive ----
// The current relay acts as a professional testnet storage gateway. Chunks are ciphertext
// only. The same protocol can be implemented by independent storage nodes; PoUS challenge
// and Sybil-resistant chain settlement remain testnet roadmap items.
async function deriveArchiveKey(){if(!me?.sigSecretKey)return null;const priv=unb64(me.sigSecretKey),domain=enc.encode('FREE-ARCHIVE-KEY-1:');const material=new Uint8Array(domain.length+priv.length);material.set(domain);material.set(priv,domain.length);const digest=new Uint8Array(await crypto.subtle.digest('SHA-512',material));return crypto.subtle.importKey('raw',digest.slice(0,32),'AES-GCM',false,['encrypt','decrypt'])}
async function encryptArchiveMessage(contactId,m){const key=await deriveArchiveKey();if(!key)throw new Error('Archive key unavailable');const iv=crypto.getRandomValues(new Uint8Array(12));const c=contacts[contactId]||null;const clean={msgId:m.msgId,from:m.from,to:m.to,text:m.text,sentAt:m.sentAt,status:m.status==='read'?'read':m.status==='delivered'?'delivered':'stored',suite:m.suite||CRYPTO_SUITE};const payload={format:'FREE-ARCHIVE-MSG-1',accountId:me.id,contactId,contactCard:c?{id:c.id,shortId:c.shortId,displayName:c.displayName,name:c.name,cryptoSuite:c.cryptoSuite,kemPublicKey:c.kemPublicKey,sigPublicKey:c.sigPublicKey}:null,message:clean};const plain=enc.encode(JSON.stringify(payload));const ct=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,plain));const packed=new Uint8Array(iv.length+ct.length);packed.set(iv);packed.set(ct,iv.length);return packed}
async function decryptArchiveMessage(ciphertext){const packed=unb64(ciphertext);if(packed.length<29)throw new Error('bad archive chunk');const key=await deriveArchiveKey(),iv=packed.slice(0,12),ct=packed.slice(12);const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv},key,ct);const x=JSON.parse(dec.decode(plain));if(x.format!=='FREE-ARCHIVE-MSG-1'||x.accountId!==me.id||!x.message?.msgId)throw new Error('archive identity mismatch');return x}
function requestArchiveChunk(cid){if(ws?.readyState!==1)return Promise.reject(new Error('offline'));const requestId=uuid();return new Promise((resolve,reject)=>{pendingArchive.set(requestId,{resolve,reject});ws.send(JSON.stringify({type:'archive-get',requestId,cid}));setTimeout(()=>{if(pendingArchive.has(requestId)){pendingArchive.delete(requestId);reject(new Error('archive fetch timeout'))}},8000)})}
async function hydrateArchive(items=[],revision=0){const recent=(Array.isArray(items)?items:[]).slice().sort((a,b)=>(Number(a.storedAt)||0)-(Number(b.storedAt)||0)).slice(-500);let changed=false,restored=0;for(const it of recent){if(!it?.msgId||!it?.cid)continue;archivedMsgIds.add(it.msgId);let exists=false;for(const arr of Object.values(chats))if((arr||[]).some(m=>m.msgId===it.msgId)){exists=true;break}if(exists)continue;try{const r=await requestArchiveChunk(it.cid),x=await decryptArchiveMessage(r.ciphertext);if(x.contactCard&&x.contactId&&!contacts[x.contactId]&&await validateCard(x.contactCard)){contacts[x.contactId]=x.contactCard;changed=true}chats[x.contactId]=chats[x.contactId]||[];if(!chats[x.contactId].some(m=>m.msgId===x.message.msgId)){chats[x.contactId].push(x.message);chats[x.contactId].sort((a,b)=>(Number(a.sentAt)||0)-(Number(b.sentAt)||0));changed=true;restored++}}catch(e){console.warn('archive hydrate',e.message)}}await setKV('archivedMsgIds',[...archivedMsgIds].slice(-50000));await setKV('archiveManifestRevision',Number(revision)||0);if(changed){await setKV('contacts',contacts);await setKV('chats',chats);await saveLocalSafetySnapshot();renderContacts();renderChat();scheduleVaultSync()}console.info(`FREE archive hydrated: ${restored} message(s), manifest revision ${Number(revision)||0}`)}
function scheduleArchiveSync(){clearTimeout(archiveTimer);archiveTimer=setTimeout(()=>syncArchive().catch(e=>console.warn('archive sync',e)),500)}
async function storeArchiveChunkHttp(contactId,m){
  const packed=await encryptArchiveMessage(contactId,m),cid=await sha256hex(packed);
  const bytes=enc.encode(`FREE-ARCHIVE-PUT-1:${me.id}:${m.msgId}:${cid}:${packed.byteLength}`);
  const signature=await Promise.resolve(pq().sign(bytes,me.sigSecretKey));
  const body={v:1,suite:CRYPTO_SUITE,accountId:me.id,msgId:m.msgId,cid,ciphertext:b64(packed),signature,card:cardForMe()};
  const r=await fetch('/api/archive/chunk',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(body)});
  let out={};try{out=await r.json()}catch{}
  if(!r.ok)throw new Error(out.error||`archive store rejected (${r.status})`);
  return out;
}
async function syncArchive(){if(archiveBusy||!me)return;archiveBusy=true;try{for(const [contactId,arr] of Object.entries(chats)){for(const m of arr||[]){if(!m?.msgId||archivedMsgIds.has(m.msgId)||!m.text)continue;try{await storeArchiveChunkHttp(contactId,m);archivedMsgIds.add(m.msgId)}catch(e){console.warn('archive store failed',m.msgId,e.message)}}}await setKV('archivedMsgIds',[...archivedMsgIds].slice(-50000));let trimmed=false;for(const id of Object.keys(chats)){const arr=chats[id]||[];if(arr.length>250){const cut=arr.length-250;if(arr.slice(0,cut).every(m=>archivedMsgIds.has(m.msgId))){chats[id]=arr.slice(-250);trimmed=true}}}if(trimmed)await setKV('chats',chats)}finally{archiveBusy=false}}
function unreadCount(id){return (chats[id]||[]).filter(m=>m.from===id&&!m.readAt).length}
async function markConversationRead(id){
 if(!id||!contacts[id])return;
 const ids=[]; for(const m of chats[id]||[]){if(m.from===id&&!m.readAt){m.readAt=Date.now();ids.push(m.msgId)}}
 if(ids.length&&readReceiptsEnabled&&ws?.readyState===1)ws.send(JSON.stringify({type:'read',from:me.id,to:id,msgIds:ids.slice(-100)}));
 if(ids.length){await saveState();renderContacts();renderChat()}
}
function renderBlocked(){
 const box=$('#blockedList'); if(!box)return; box.innerHTML='';
 const ids=Object.keys(blockedIds||{});
 if(!ids.length){box.innerHTML=`<div class="mini">${esc(t('noBlocked'))}</div>`;return}
 for(const id of ids){
   const row=document.createElement('div'); row.className='blocked-row';
   row.innerHTML=`<div><strong>${esc(blockedIds[id]?.name||blockedIds[id]?.shortId||id.slice(0,12))}</strong><small>${esc(blockedIds[id]?.shortId||id)}</small></div><button class="btn ghost" type="button">${esc(t('unblock'))}</button>`;
   row.querySelector('button').onclick=async()=>{delete blockedIds[id];await saveState();renderBlocked()};
   box.appendChild(row);
 }
}
async function removeSelectedContact(){
 if(!selectedId||!contacts[selectedId])return;
 const name=contacts[selectedId].name||contacts[selectedId].displayName||contacts[selectedId].shortId;
 if(!confirm(currentLang==='vi'?`Xóa ${name} khỏi danh bạ? Lịch sử chat cục bộ cũng sẽ bị xóa.`:`Remove ${name}? Local chat history will also be deleted.`))return;
 delete contacts[selectedId];delete chats[selectedId];selectedId=null;await saveState();renderContacts();renderChat()
}
async function blockSelectedContact(){
 if(!selectedId||!contacts[selectedId])return;
 const c=contacts[selectedId],id=selectedId,name=c.name||c.displayName||c.shortId;
 if(!confirm(currentLang==='vi'?`Chặn ${name}? FREE sẽ bỏ qua tin nhắn mới từ ID này trên thiết bị này.`:`Block ${name}? FREE will ignore new messages from this ID on this device.`))return;
 blockedIds[id]={name,shortId:c.shortId,blockedAt:Date.now()};delete contacts[id];delete chats[id];selectedId=null;await saveState();renderContacts();renderChat();renderBlocked()
}
function validPin(pin){return /^\d{4,6}$/.test(pin)}
const RB32='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
function base32(bytes){let bits=0,val=0,out='';for(const b of bytes){val=(val<<8)|b;bits+=8;while(bits>=5){out+=RB32[(val>>>(bits-5))&31];bits-=5}}if(bits)out+=RB32[(val<<(5-bits))&31];return out}
function unbase32(text){const clean=String(text||'').toUpperCase().replace(/[^A-Z2-7]/g,'');let bits=0,val=0,out=[];for(const ch of clean){const n=RB32.indexOf(ch);if(n<0)throw new Error('Invalid Recovery Secret');val=(val<<5)|n;bits+=5;if(bits>=8){out.push((val>>>(bits-8))&255);bits-=8}}return new Uint8Array(out)}
function groups(text,n=4){return text.match(new RegExp(`.{1,${n}}`,'g')).join('-')}
async function recoveryAddress(secret){const h=new Uint8Array(await crypto.subtle.digest('SHA-512',new Uint8Array([...enc.encode('FREE-RECOVERY-ADDRESS-2:'),...secret])));return 'FR-'+groups(base32(h.slice(0,13)).slice(0,20))}
function compactSecret(secret){return groups(base32(secret))}
async function deriveAccountRecoveryKey(secret,pin,salt){const material=new Uint8Array(secret.length+pin.length);material.set(secret);material.set(enc.encode(pin),secret.length);const base=await crypto.subtle.importKey('raw',material,'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',hash:'SHA-512',salt,iterations:600000},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function buildRecoveryCapsule(pin,secretOverride=null){if(!validPin(pin))throw new Error(currentLang==='vi'?'PIN phải gồm 4–6 chữ số.':'PIN must contain 4–6 digits.');const secret=secretOverride||crypto.getRandomValues(new Uint8Array(20)),salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12));const key=await deriveAccountRecoveryKey(secret,pin,salt);/* FREE-031: Recovery restores cryptographic account authority; long-term history is restored from the encrypted account vault/archive, not duplicated forever inside the Recovery capsule. */const payload={format:'FREE-ACCOUNT-3',identity:me.raw,profile,blockedIds,recoveryModel:'identity-plus-network-archive',createdAt:Date.now()};const ct=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,enc.encode(JSON.stringify(payload))));const address=await recoveryAddress(secret);return{address,secret,capsule:{v:3,suite:CRYPTO_SUITE,address,salt:b64url(salt),iv:b64url(iv),ciphertext:b64url(ct)}}}
async function uploadRecoveryCapsule(capsule){const r=await fetch('/api/recovery-capsule?address='+encodeURIComponent(capsule.address),{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(capsule)});if(!r.ok)throw new Error(currentLang==='vi'?'Không thể lưu recovery capsule lên FREE Network.':'Could not store recovery capsule on FREE Network.');return r.json()}
async function fetchRecoveryCapsule(address){const r=await fetch('/api/recovery-capsule?address='+encodeURIComponent(address),{cache:'no-store'});if(!r.ok)throw new Error(currentLang==='vi'?'Không tìm thấy Recovery Address.':'Recovery Address not found.');return r.json()}
async function decryptRecoveryCapsule(address,secretText,pin){if(!validPin(pin))throw new Error(currentLang==='vi'?'PIN phải gồm 4–6 chữ số.':'PIN must contain 4–6 digits.');const secret=unbase32(secretText);const expected=await recoveryAddress(secret);if(expected!==address.toUpperCase())throw new Error(currentLang==='vi'?'Recovery Address và Secret không khớp.':'Recovery Address and Secret do not match.');const cap=await fetchRecoveryCapsule(expected),key=await deriveAccountRecoveryKey(secret,pin,unb64url(cap.salt));let plain;try{plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64url(cap.iv)},key,unb64url(cap.ciphertext))}catch{throw new Error(currentLang==='vi'?'Recovery Secret hoặc PIN không đúng.':'Recovery Secret or PIN is incorrect.')}const state=JSON.parse(dec.decode(plain));if(!['FREE-ACCOUNT-2','FREE-ACCOUNT-3'].includes(state.format)||!state.identity)throw new Error('Invalid FREE recovery capsule');const id=await identityId(state.identity.kemPublicKey,state.identity.sigPublicKey);if(id!==state.identity.id)throw new Error('Recovery identity integrity check failed');return{state,secret}}
// FREE-RK1 compatibility for migration only.
async function buildAccountRecoveryKit(pin,secretOverride=null){const secret=secretOverride||crypto.getRandomValues(new Uint8Array(32)),salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await deriveAccountRecoveryKey(secret,pin,salt);const payload={format:'FREE-ACCOUNT-1',identity:me.raw,profile,contacts,chats,createdAt:Date.now()};const ct=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,enc.encode(JSON.stringify(payload))));return 'FREE-RK1.'+b64url(enc.encode(JSON.stringify({v:1,suite:CRYPTO_SUITE,salt:b64url(salt),iv:b64url(iv),secret:b64url(secret),ciphertext:b64url(ct)})))}
function parseAccountKit(text){if(!text.startsWith('FREE-RK1.'))throw new Error(currentLang==='vi'?'Recovery Kit cũ không hợp lệ.':'Invalid legacy Recovery Kit.');return JSON.parse(dec.decode(unb64url(text.slice(9))))}
async function decryptAccountRecoveryKit(text,pin){const kit=parseAccountKit(text),secret=unb64url(kit.secret),key=await deriveAccountRecoveryKey(secret,pin,unb64url(kit.salt));let plain;try{plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64url(kit.iv)},key,unb64url(kit.ciphertext))}catch{throw new Error(currentLang==='vi'?'Recovery Kit hoặc PIN không đúng.':'Recovery Kit or PIN is incorrect.')}const state=JSON.parse(dec.decode(plain));return{state,secret}}
async function saveNewAccountKit(pin){const r=await buildRecoveryCapsule(pin);await uploadRecoveryCapsule(r.capsule);await setKV('recoveryAddress',r.address);await setKV('recoverySecret',compactSecret(r.secret));await setKV('accountRecoveryKit','');if($('#accountRecoveryAddress'))$('#accountRecoveryAddress').value=r.address;if($('#accountRecoverySecret'))$('#accountRecoverySecret').value=compactSecret(r.secret);return r}
function normalizeFreeName(name){let n=String(name||'').trim().toLowerCase().replace(/^@/,'');if(!n.endsWith('.free'))n+='.free';if(!/^[a-z0-9][a-z0-9._-]{1,27}\.free$/.test(n))throw new Error(currentLang==='vi'?'FREE Name phải dài 2–28 ký tự trước .free và chỉ dùng a-z, 0-9, ., _, -.':'FREE Name must be 2–28 characters before .free using a-z, 0-9, ., _, -.');return n}
function validSecretNumber(v){const x=String(v||'');return /^\d{10}$/.test(x)&&!(/^(\d)\1{9}$/.test(x))&&!['0123456789','9876543210','1234567890','0987654321'].includes(x)}
async function deriveEasyWrapKey(name,secretNumber,pin,salt){const text=`FREE-EASY-RECOVERY-1:${normalizeFreeName(name)}:${secretNumber}:${pin}`;const base=await crypto.subtle.importKey('raw',enc.encode(text),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',hash:'SHA-512',salt,iterations:900000},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function registerEasyRecovery(name,secretNumber,pin){if(!me)throw new Error('Identity unavailable');name=normalizeFreeName(name);if(!validSecretNumber(secretNumber))throw new Error(currentLang==='vi'?'10-digit Secret phải đúng 10 chữ số.':'10-digit Secret must contain exactly 10 digits.');if(!validPin(pin))throw new Error(currentLang==='vi'?'PIN phải gồm 4–6 chữ số.':'PIN must contain 4–6 digits.');let address=await getKV('recoveryAddress'),secretText=await getKV('recoverySecret');if(!address||!secretText){const r=await saveNewAccountKit(pin);address=r.address;secretText=compactSecret(r.secret)}else{const secretBytes=unbase32(secretText),expected=await recoveryAddress(secretBytes);if(expected!==String(address).toUpperCase()){const r=await saveNewAccountKit(pin);address=r.address;secretText=compactSecret(r.secret)}else{const probe=await fetch('/api/recovery-capsule?address='+encodeURIComponent(expected),{cache:'no-store'});if(probe.ok){await decryptRecoveryCapsule(expected,secretText,pin)}else if(probe.status===404){const rebuilt=await buildRecoveryCapsule(pin,secretBytes);await uploadRecoveryCapsule(rebuilt.capsule);address=rebuilt.address;await setKV('recoveryAddress',address)}else{throw new Error(currentLang==='vi'?'Không thể kiểm tra Recovery trên FREE Network.':'Could not verify Recovery on FREE Network.')}}}const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await deriveEasyWrapKey(name,secretNumber,pin,salt),secretBytes=unbase32(secretText);const wrapped=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,secretBytes));const card=cardForMe();const digest=hex(await crypto.subtle.digest('SHA-512',wrapped));const signed=enc.encode(`FREE-EASY-RECOVERY-REGISTER-1:${name}:${me.id}:${address}:${digest}`);const signature=await Promise.resolve(pq().sign(signed,me.sigSecretKey));const body={v:1,suite:CRYPTO_SUITE,name,accountId:me.id,address,salt:b64url(salt),iv:b64url(iv),wrappedSecret:b64url(wrapped),card,signature};const res=await fetch('/api/easy-recovery',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||'Could not save Easy Recovery');await setKV('easyFreeName',name);return{name,address}}
async function restoreEasyRecovery(name,secretNumber,pin){name=normalizeFreeName(name);if(!validSecretNumber(secretNumber)||!validPin(pin))throw new Error(currentLang==='vi'?'Kiểm tra lại 10-digit Secret và PIN.':'Check the 10-digit Secret and PIN.');const res=await fetch('/api/easy-recovery?name='+encodeURIComponent(name),{cache:'no-store'});const rec=await res.json().catch(()=>({}));if(!res.ok)throw new Error(currentLang==='vi'?'Không tìm thấy FREE Name hoặc thông tin khôi phục chưa đúng.':'FREE Name not found or recovery information is unavailable.');const key=await deriveEasyWrapKey(name,secretNumber,pin,unb64url(rec.salt));let secret;try{secret=new Uint8Array(await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64url(rec.iv)},key,unb64url(rec.wrappedSecret)))}catch{throw new Error(currentLang==='vi'?'10-digit Secret hoặc PIN không đúng.':'10-digit Secret or PIN is incorrect.')}const result=await decryptRecoveryCapsule(rec.address,compactSecret(secret),pin);return{...result,address:rec.address,secretText:compactSecret(secret),easyFreeName:name}}
function recoveryCard(){return `FREE RECOVERY CARD v2\nRecovery Address: ${$('#accountRecoveryAddress').value||''}\nRecovery Secret: ${$('#accountRecoverySecret').value||''}\n\nKeep the Recovery Secret private. PIN is not stored on this card.`}
function downloadText(name,text){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function inviteLink(){return `${location.origin}/#freeid=${me.id}`}
function renderIdentity(){if(!me)return;const link=inviteLink(),name=profile?.displayName||'FREE';$('#myId').textContent=me.id;$('#shortId').textContent=me.shortId;$('#displayNameHeading').textContent=name;$('#profileName').value=name;$('#inviteLink').value=link;$('#qr').src=`/api/qr?text=${encodeURIComponent(link)}`;if($('#headerName'))$('#headerName').textContent=name;if($('#headerShortId'))$('#headerShortId').textContent=me.shortId;if($('#settingsName'))$('#settingsName').textContent=name;if($('#settingsShortId'))$('#settingsShortId').textContent=me.shortId;const kit=$('#accountRecoveryKit');if(kit)getKV('accountRecoveryKit').then(v=>{if(v)kit.value=v});getKV('recoveryAddress').then(v=>{if(v&&$('#accountRecoveryAddress'))$('#accountRecoveryAddress').value=v});getKV('recoverySecret').then(v=>{if(v&&$('#accountRecoverySecret'))$('#accountRecoverySecret').value=v});getKV('easyFreeName').then(v=>{if(v&&$('#easyFreeName'))$('#easyFreeName').value=v})}
function renderContacts(){const box=$('#contacts');if(!box)return;box.innerHTML='';const ids=Object.keys(contacts);if(!ids.length){box.innerHTML=`<div class="muted empty">${esc(t('noContacts'))}</div>`;return}for(const id of ids){const c=contacts[id],b=document.createElement('button'),n=unreadCount(id);b.className='contact'+(id===selectedId?' active':'');b.innerHTML=`<div class="contact-copy"><strong>${esc(c.name||c.displayName||'FREE '+(c.shortId||id.slice(0,10)))}</strong><span>${esc(c.shortId||id)}</span></div>${n?`<b class="unread-badge">${n>99?'99+':n}</b>`:''}`;b.onclick=()=>{selectedId=id;renderContacts();renderChat();document.querySelector('.messenger-layout')?.classList.add('chat-open');markConversationRead(id)};box.appendChild(b)}}
function renderChat(){const title=$('#chatTitle'),msgs=$('#messages'),composer=$('#composer');if(!title||!msgs||!composer)return;if(!selectedId||!contacts[selectedId]){title.textContent=t('selectContact');$('#chatActions')?.setAttribute('hidden','');msgs.innerHTML=`<div class="muted empty">${esc(t('chooseContact'))}</div>`;composer.hidden=true;return}title.textContent=contacts[selectedId].name||contacts[selectedId].displayName||`FREE ${contacts[selectedId].shortId||selectedId.slice(0,10)}`;$('#chatActions')?.removeAttribute('hidden');composer.hidden=false;msgs.innerHTML='';for(const m of chats[selectedId]||[]){const d=document.createElement('div');d.className='msg '+(m.from===me.id?'mine':'theirs');const st=m.from===me.id?messageStatusMarkup(m):'';d.innerHTML=`<div>${esc(m.text)}</div><div class="msg-meta"><time>${new Date(m.sentAt).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</time>${st}</div>`;msgs.appendChild(d)}msgs.scrollTop=msgs.scrollHeight}

function messageStatusMarkup(m){
 const st=m.status||'sent';
 if(st==='offline'||st==='sending'||st==='queued')return `<span class="msg-status pending" title="${esc(st)}">◷</span>`;
 if(st==='read')return `<span class="msg-status read" title="${currentLang==='vi'?'Đã đọc':'Read'}">✓✓</span>`;
 if(st==='delivered')return `<span class="msg-status delivered" title="${currentLang==='vi'?'Đã nhận':'Delivered'}">✓✓</span>`;
 return `<span class="msg-status sent" title="${currentLang==='vi'?'Đã gửi':'Sent'}">✓</span>`;
}
let networkDevices=[];
function renderDeviceList(){const box=$('#deviceList');if(!box||!deviceId)return;const list=networkDevices.length?networkDevices:[{deviceId,current:true,online:ws?.readyState===1,lastSeen:Date.now()}];box.innerHTML=list.map(d=>`<div class="device-row"><div><strong>${esc(d.current?t('thisDevice'):'Device')}</strong><small>${esc(d.deviceId)} · ${d.online?'online':('last seen '+new Date(d.lastSeen||0).toLocaleString())}</small></div>${d.current?'<span class="device-current">current</span>':d.revokedAt?'<span class="device-current">revoked</span>':`<button class="device-revoke" data-device="${esc(d.deviceId)}">Revoke</button>`}</div>`).join('');box.querySelectorAll('.device-revoke').forEach(b=>b.onclick=()=>revokeDevice(b.dataset.device))}
async function revokeDevice(targetDeviceId){if(!confirm(currentLang==='vi'?'Thu hồi thiết bị này? Thiết bị đó sẽ bị ngắt khỏi FREE.':'Revoke this device? It will be disconnected from FREE.'))return;const bytes=enc.encode(`FREE-DEVICE-REVOKE-1:${me.id}:${targetDeviceId}`);const signature=await Promise.resolve(pq().sign(bytes,me.sigSecretKey));if(ws?.readyState!==1)throw new Error('FREE relay is offline');ws.send(JSON.stringify({type:'device-revoke',targetDeviceId,signature}))}
async function lockApp(){if(!appLockEnabled||!me||!profile)return;isUnlocked=false;$('#appShell').hidden=true;$('#lockScreen').hidden=false;$('#unlockPin').value='';$('#unlockError').textContent='';setTimeout(()=>$('#unlockPin').focus(),0)}
async function unlockApp(){const pin=$('#unlockPin').value.trim(),addr=await getKV('recoveryAddress'),secret=await getKV('recoverySecret');try{await decryptRecoveryCapsule(addr,secret,pin);isUnlocked=true;$('#lockScreen').hidden=true;showApp()}catch(e){$('#unlockError').textContent=e.message}}

function status(text,good=true){const e=$('#status');if(!e)return;e.textContent=text;e.dataset.good=good?'1':'0'}
function updateStorageText(){const e=$('#storageState');if(e)e.textContent=storageEnabled?t('storageOn'):t('storageOff')}
function renderService(x){if(!x)return;$('#testCredits').textContent=Number(x.credits||0).toFixed(3);$('#serviceStats').textContent=`${Number(x.storedBytes||0).toLocaleString()} bytes · ${x.receipts||0} receipts · capacity ${x.capacityMb||0} MB`;}
function animateIn(el,kind='panel'){if(!el||matchMedia('(prefers-reduced-motion: reduce)').matches)return;try{el.animate(kind==='app'?[{opacity:0,transform:'translateY(8px) scale(.995)'},{opacity:1,transform:'translateY(0) scale(1)'}]:[{opacity:0,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],{duration:220,easing:'cubic-bezier(.2,.8,.2,1)'})}catch{}}
function showStep(id){let active=null;['welcomeStep','createStep','recoveryStep','createdStep'].forEach(x=>{const el=$('#'+x),on=x===id;el.hidden=!on;if(on)active=el});animateIn(active)}
function showApp(){const onboarding=$('#onboarding'),app=$('#appShell');onboarding.hidden=true;onboarding.setAttribute('aria-hidden','true');app.hidden=false;app.removeAttribute('aria-hidden');document.body.classList.add('in-app');window.scrollTo(0,0);showView('chatsView');renderIdentity();renderContacts();renderChat();renderBlocked();animateIn(app,'app');connect()}
function showView(id){let active=null;document.querySelectorAll('.app-view').forEach(v=>{const on=v.id===id;v.hidden=!on;v.classList.toggle('active-view',on);if(on)active=v});document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===id));window.scrollTo({top:0,left:0,behavior:'instant'});animateIn(active);if(id==='settingsView'){const a=$('#displayNameHeading'),b=$('#shortId');if($('#settingsName'))$('#settingsName').textContent=a?.textContent||profile?.name||'FREE';if($('#settingsShortId'))$('#settingsShortId').textContent=b?.textContent||shortId(me?.id||'')} }
async function addContactCard(card,name){if(!(await validateCard(card)))throw new Error('Invalid or non-PQ FREE identity');if(card.id===me.id)throw new Error('This is your own identity');delete blockedIds[card.id];contacts[card.id]={...card,name:name||card.displayName||contacts[card.id]?.name||`FREE ${card.shortId||card.id.slice(0,10)}`};await saveState();renderContacts();return contacts[card.id]}
async function fetchCardById(id){if(!/^[a-f0-9]{64}$/i.test(id))throw new Error('Invalid FREE full identity');const r=await fetch(`/api/card?id=${encodeURIComponent(id)}`,{cache:'no-store'});if(!r.ok)throw new Error('Identity is not currently published on this relay');const card=await r.json();if(!(await validateCard(card))||card.id.toLowerCase()!==id.toLowerCase())throw new Error('Relay returned an invalid identity card');return card}
async function parseInvite(input){const raw=input.trim();let id='';try{const u=new URL(raw,location.origin);id=(u.hash.match(/#freeid=([a-f0-9]{64})/i)||[])[1]||''}catch{}if(!id&&/^[a-f0-9]{64}$/i.test(raw))id=raw;if(!id)throw new Error('Paste a FREE-PQ invite link or full FREE identity');return fetchCardById(id.toLowerCase())}
async function addFromInvite(input){const card=await parseInvite(input);await addContactCard(card);selectedId=card.id;renderContacts();renderChat();if(ws?.readyState===1){const mine=cardForMe();const signature=await signObject(mine);ws.send(JSON.stringify({type:'contact-card',from:me.id,to:card.id,card:mine,signature}))}return card}

function connect(){
 if(!me)return;
 if(ws&&(ws.readyState===WebSocket.OPEN||ws.readyState===WebSocket.CONNECTING))return;
 clearTimeout(reconnectTimer);clearTimeout(authTimer);
 const generation=++connectGeneration,proto=location.protocol==='https:'?'wss':'ws';
 status(t('reconnecting'),false);
 const sock=new WebSocket(`${proto}://${location.host}/ws`);ws=sock;
 sock.onopen=()=>{if(generation!==connectGeneration)return;status(t('authenticating'),false);authTimer=setTimeout(()=>{if(generation===connectGeneration&&sock.readyState===WebSocket.OPEN){status(t('authTimeout'),false);try{sock.close(4001,'client auth timeout')}catch{}}},45000)};
 sock.onclose=()=>{if(generation!==connectGeneration)return;clearTimeout(authTimer);status(t('reconnecting'),false);reconnectTimer=setTimeout(connect,2000)};
 sock.onerror=()=>{if(generation===connectGeneration)status(t('connectionError'),false)};
 sock.onmessage=e=>{if(generation!==connectGeneration)return;try{handleWs(JSON.parse(e.data),sock)}catch(err){console.error('WS message error',err)}};
}
async function handleWs(msg,sock=ws){
  if(msg.type==='challenge'){try{status(t('authenticating'),false);const card=cardForMe();const authText=enc.encode(`FREE-AUTH-2:${me.id}:${deviceId}:${msg.challenge}`);const signature=await Promise.resolve(pq().sign(authText,me.sigSecretKey));if(sock?.readyState===WebSocket.OPEN)sock.send(JSON.stringify({type:'hello-auth',id:me.id,deviceId,challenge:msg.challenge,card,signature}));}catch(err){console.error('PQ auth sign error',err);status(`${t('authFailed')} · local-sign-error`,false);try{sock?.close(4002,'local sign error')}catch{}}return}
  if(msg.type==='hello-ok'){clearTimeout(authTimer);status(t('connected'));if(sock?.readyState===1)sock.send(JSON.stringify({type:'device-list-request'}));await pullVaultState().catch(e=>console.warn('vault hydration deferred',e));if(sock?.readyState===1)sock.send(JSON.stringify({type:'archive-manifest-request'}));scheduleArchiveSync();await resendOutbox();if(storageEnabled&&sock?.readyState===WebSocket.OPEN)sock.send(JSON.stringify({type:'storage-advertise',enabled:true,nodeId:nodeServiceId,capacityMb:nodeCapacityMb}));return}
  if(msg.type==='device-list'){networkDevices=Array.isArray(msg.devices)?msg.devices:[];renderDeviceList();return}
  if(msg.type==='device-error'){alert(msg.reason||'Device operation failed');return}
  if(msg.type==='auth-error'){clearTimeout(authTimer);status(`${t('authFailed')}${msg.reason?' · '+msg.reason:''}`,false);return}
  if(msg.type==='ack'){for(const id of Object.keys(chats)){const m=(chats[id]||[]).find(x=>x.msgId===msg.msgId);if(m){m.status=msg.queued?'queued':'sent';await saveState();if(id===selectedId)renderChat();break}}return}
  if(msg.type==='delivery'){for(const id of Object.keys(chats)){const m=(chats[id]||[]).find(x=>x.msgId===msg.msgId);if(m){m.status='delivered';await saveState();if(id===selectedId)renderChat();break}}return}
  if(msg.type==='read'){const ids=new Set(Array.isArray(msg.msgIds)?msg.msgIds:[]);for(const cid of Object.keys(chats)){let changed=false;for(const m of chats[cid]||[]){if(m.from===me.id&&ids.has(m.msgId)){m.status='read';changed=true}}if(changed){await saveState();if(cid===selectedId)renderChat()}}return}
  if(msg.type==='contact-card'){
    if(blockedIds?.[msg.from])return;
    const ok=(await validateCard(msg.card))&&await verifyObject(msg.card,msg.signature,msg.card.sigPublicKey);if(ok&&msg.card.id===msg.from){await addContactCard(msg.card);renderContacts()}
    return;
  }
  if(msg.type==='envelope'){await receiveEnvelope(msg);return}
  if(msg.type==='archive-manifest'){await hydrateArchive(msg.items||[],msg.revision||0);return}
  if(msg.type==='archive-chunk'){const p=pendingArchive.get(msg.requestId);if(p){pendingArchive.delete(msg.requestId);p.resolve(msg)}return}
  if(msg.type==='archive-stored'){const p=pendingArchive.get(msg.requestId);if(p){pendingArchive.delete(msg.requestId);p.resolve(msg)}return}
  if(msg.type==='archive-error'){const p=pendingArchive.get(msg.requestId);if(p){pendingArchive.delete(msg.requestId);p.reject(new Error(msg.reason||'archive error'))}return}
  if(msg.type==='storage-peers'){pendingVault.get(msg.requestId)?.resolve(msg.peers||[]);pendingVault.delete(msg.requestId);return}
  if(msg.type==='vault-store'){await receiveShard(msg);return}
  if(msg.type==='vault-store-ack'){const p=pendingVault.get(`store:${msg.cid}`);if(p){p.acks.add(msg.from);p.update?.()};return}
  if(msg.type==='vault-fetch'){await serveShard(msg);return}
  if(msg.type==='vault-response'){const p=pendingVault.get(msg.requestId);if(p&&msg.share){p.shares.set(msg.cid,msg.share);p.update?.();if(p.shares.size>=p.k)p.resolve([...p.shares.values()])};return}
  if(msg.type==='storage-status'){$('#storageCount').textContent=String(msg.available||0);if(msg.service)renderService(msg.service);return}
  if(msg.type==='service-credit'){if(msg.service)renderService(msg.service);return}
}
async function sendMessage(text){
  if(!selectedId||!contacts[selectedId])return;const c=contacts[selectedId];if(c.cryptoSuite!==CRYPTO_SUITE)throw new Error('This contact uses an obsolete classical identity. Re-add their FREE-PQ identity.');
  const msgId=uuid(),sentAt=Date.now();const kem=pq().encapsulate(c.kemPublicKey);const key=await messageKey(kem.sharedSecret,me.id,c.id,msgId);const iv=crypto.getRandomValues(new Uint8Array(12));const aad=aadFor(me.id,c.id,msgId,sentAt,kem.cipherText);const ciphertext=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:aad},key,enc.encode(text));
  const signable={suite:CRYPTO_SUITE,from:me.id,to:c.id,msgId,sentAt,kemCiphertext:kem.cipherText,iv:b64(iv),ciphertext:b64(ciphertext)};const signature=await signObject(signable);const payload={...signable,signature};
  // Carry the sender's public self-certifying card with every new envelope. This lets a
  // restored/new device authenticate the sender and receive the message even when its
  // local contact list has not been synchronized yet. No secret material is included.
  const wire={type:'envelope',from:me.id,to:c.id,payload,senderCard:cardForMe()};chats[c.id]=chats[c.id]||[];chats[c.id].push({msgId,from:me.id,to:c.id,text,sentAt,status:'sending',suite:CRYPTO_SUITE,wire});await saveState();renderChat();if(ws?.readyState!==1){chats[c.id].at(-1).status='offline';await saveState();renderChat();return}ws.send(JSON.stringify(wire))
}
async function resendOutbox(){if(ws?.readyState!==1)return;let changed=false;for(const id of Object.keys(chats)){for(const m of chats[id]||[]){if(m.from===me.id&&m.wire&&['offline','sending'].includes(m.status)){ws.send(JSON.stringify(m.wire));m.status='sending';changed=true}}}if(changed){await saveState();renderChat()}}
async function receiveEnvelope(msg){
  if(blockedIds?.[msg.from])return;
  // A clean/restored device may not have the sender in its local contact list yet.
  // Recover only from a self-certifying public card whose fingerprint is the envelope
  // sender ID; the envelope signature is then verified with that card before decryption.
  let c=contacts[msg.from];
  if((!c||c.cryptoSuite!==CRYPTO_SUITE)&&msg.senderCard){
    const card=msg.senderCard;
    if(card.id===msg.from&&await validateCard(card)){await addContactCard(card);c=contacts[msg.from];renderContacts()}
  }
  if(!c||c.cryptoSuite!==CRYPTO_SUITE)return;const p=msg.payload;if(p.suite!==CRYPTO_SUITE||p.from!==msg.from||p.to!==msg.to)return;
  const signable={suite:p.suite,from:p.from,to:p.to,msgId:p.msgId,sentAt:p.sentAt,kemCiphertext:p.kemCiphertext,iv:p.iv,ciphertext:p.ciphertext};const ok=await verifyObject(signable,p.signature,c.sigPublicKey);if(!ok)return;
  try{const shared=pq().decapsulate(p.kemCiphertext,me.kemSecretKey);const key=await messageKey(shared,p.from,p.to,p.msgId);const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(p.iv),additionalData:aadFor(p.from,p.to,p.msgId,p.sentAt,p.kemCiphertext)},key,unb64(p.ciphertext));chats[msg.from]=chats[msg.from]||[];if(!chats[msg.from].some(x=>x.msgId===p.msgId))chats[msg.from].push({msgId:p.msgId,from:msg.from,to:me.id,text:dec.decode(plain),sentAt:p.sentAt,status:'received',suite:CRYPTO_SUITE});await saveState();if(selectedId===msg.from){renderChat();await markConversationRead(msg.from)}else renderContacts();if(ws?.readyState===1)ws.send(JSON.stringify({type:'delivery',from:me.id,to:msg.from,msgId:p.msgId}))}catch(e){console.warn('PQ decrypt failed',e)}
}

// ---- Distributed encrypted vault (experimental) ----
function gfMul(a,b){let p=0;for(let i=0;i<8;i++){if(b&1)p^=a;const hi=a&0x80;a=(a<<1)&255;if(hi)a^=0x1b;b>>=1}return p}
function gfPow(a,n){let r=1;while(n){if(n&1)r=gfMul(r,a);a=gfMul(a,a);n>>=1}return r}
function gfInv(a){if(!a)throw new Error('GF divide by zero');return gfPow(a,254)}
function gfDiv(a,b){return a?gfMul(a,gfInv(b)):0}
function shamirSplit(data,n=5,k=3){const shares=Array.from({length:n},(_,i)=>({x:i+1,data:new Uint8Array(data.length)}));const coeff=new Uint8Array(k);for(let pos=0;pos<data.length;pos++){coeff[0]=data[pos];crypto.getRandomValues(coeff.subarray(1));for(const sh of shares){let y=coeff[k-1];for(let j=k-2;j>=0;j--)y=gfMul(y,sh.x)^coeff[j];sh.data[pos]=y}}return shares}
function shamirCombine(shares,k=3){const use=shares.slice(0,k),len=use[0].data.length,out=new Uint8Array(len);for(let pos=0;pos<len;pos++){let secret=0;for(let i=0;i<use.length;i++){let li=1;for(let j=0;j<use.length;j++){if(i===j)continue;li=gfMul(li,gfDiv(use[j].x,use[i].x^use[j].x))}secret^=gfMul(use[i].data[pos],li)}out[pos]=secret}return out}
async function sha256hex(data){return hex(await crypto.subtle.digest('SHA-256',data))}
async function deriveRecoveryKey(secret,salt){const material=await crypto.subtle.importKey('raw',secret,'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',hash:'SHA-256',salt,iterations:250000},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function requestStoragePeers(){if(ws?.readyState!==1)throw new Error('Relay is offline');const requestId=uuid();return new Promise((resolve,reject)=>{pendingVault.set(requestId,{resolve,reject});ws.send(JSON.stringify({type:'storage-peers',requestId}));setTimeout(()=>{if(pendingVault.has(requestId)){pendingVault.delete(requestId);reject(new Error('Storage peer lookup timed out'))}},5000)})}
async function createVault(){
  const btn=$('#backupBtn');btn.disabled=true;$('#vaultProgress').textContent='Encrypting your vault…';
  try{
    const peers=await requestStoragePeers();if(peers.length<3)throw new Error(`Need at least 3 volunteer storage nodes online; currently ${peers.length}. Open FREE on more devices and enable Storage Node.`);
    const state={format:'FREE-VAULT-1',createdAt:Date.now(),identity:me.raw,contacts,chats};const plain=enc.encode(JSON.stringify(state));
    const secret=crypto.getRandomValues(new Uint8Array(32)),salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12));const key=await deriveRecoveryKey(secret,salt);const encrypted=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,plain));const cipherHash=await sha256hex(encrypted);const shares=shamirSplit(encrypted,5,3);const vaultId=cipherHash.slice(0,32);const manifest=[];
    for(let i=0;i<shares.length;i++){
      const packed=new Uint8Array(1+shares[i].data.length);packed[0]=shares[i].x;packed.set(shares[i].data,1);const cid=await sha256hex(packed);const holders=[];const candidates=[peers[i%peers.length],peers[(i+1)%peers.length]].filter((v,j,a)=>v&&a.indexOf(v)===j);
      for(const holder of candidates){ws.send(JSON.stringify({type:'vault-store',from:me.id,to:holder,vaultId,cid,share:b64(packed)}));holders.push(holder)}
      manifest.push({cid,x:shares[i].x,holders});$('#vaultProgress').textContent=`Distributing encrypted shards ${i+1}/5…`;
    }
    const kit={format:'FREE-RECOVERY-1',vaultId,k:3,n:5,salt:b64url(salt),iv:b64url(iv),secret:b64url(secret),cipherHash,shares:manifest};const text=JSON.stringify(kit);await setKV('lastRecoveryKit',text);$('#recoveryKit').value=text;$('#vaultProgress').textContent='Vault distributed. Keep the Recovery Kit offline and private.';downloadText(`FREE-Recovery-${vaultId}.free-recovery`,text);
  }finally{btn.disabled=false}
}
async function receiveShard(msg){if(!storageEnabled)return;const packed=unb64(msg.share);if(await sha256hex(packed)!==msg.cid)return;await setKV(`shard:${msg.cid}`,{vaultId:msg.vaultId,cid:msg.cid,share:msg.share,owner:msg.from,storedAt:Date.now()});let idx=await getKV('shard-index')||[];if(!idx.includes(msg.cid))idx.push(msg.cid);await setKV('shard-index',idx.slice(-200));if(ws?.readyState===1)ws.send(JSON.stringify({type:'vault-store-ack',from:me.id,to:msg.from,cid:msg.cid,bytes:packed.byteLength}))}
async function serveShard(msg){if(!storageEnabled)return;const rec=await getKV(`shard:${msg.cid}`);if(rec&&ws?.readyState===1)ws.send(JSON.stringify({type:'vault-response',from:me.id,to:msg.from,requestId:msg.requestId,cid:msg.cid,share:rec.share}))}
async function restoreVault(){
  const raw=$('#recoveryKit').value.trim();if(!raw)throw new Error('Paste your FREE Recovery Kit first');const kit=JSON.parse(raw);if(kit.format!=='FREE-RECOVERY-1')throw new Error('Invalid Recovery Kit');if(ws?.readyState!==1)throw new Error('Relay is offline');
  $('#vaultProgress').textContent='Looking for your encrypted shards…';const requestId=uuid();const shares=new Map();const p=new Promise((resolve,reject)=>{pendingVault.set(requestId,{resolve,reject,shares,k:kit.k,update:()=>{$('#vaultProgress').textContent=`Recovered ${shares.size}/${kit.k} required shards…`}});setTimeout(()=>reject(new Error('Not enough shard holders are online yet')),12000)});
  for(const sh of kit.shares)for(const holder of sh.holders||[])ws.send(JSON.stringify({type:'vault-fetch',from:me.id,to:holder,requestId,cid:sh.cid}));
  await p;pendingVault.delete(requestId);const unpacked=[];for(const [cid,s] of shares){const packed=unb64(s);if(await sha256hex(packed)!==cid)continue;unpacked.push({x:packed[0],data:packed.slice(1)});if(unpacked.length>=kit.k)break}if(unpacked.length<kit.k)throw new Error('Recovered shards failed integrity checks');
  const encrypted=shamirCombine(unpacked,kit.k);if(await sha256hex(encrypted)!==kit.cipherHash)throw new Error('Vault reconstruction hash mismatch');const key=await deriveRecoveryKey(unb64url(kit.secret),unb64url(kit.salt));const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64url(kit.iv)},key,encrypted);const state=JSON.parse(dec.decode(plain));if(state.format!=='FREE-VAULT-1'||!state.identity?.id)throw new Error('Invalid decrypted FREE vault');
  await setKV('identity',state.identity);await setKV('contacts',state.contacts||{});await setKV('chats',state.chats||{});$('#vaultProgress').textContent='Identity and data restored. Reloading FREE…';setTimeout(()=>location.reload(),700);
}
async function toggleStorage(){storageEnabled=$('#storageToggle').checked;nodeCapacityMb=Math.max(100,Math.min(102400,Number($('#nodeCapacity').value)||1024));await setKV('nodeCapacityMb',nodeCapacityMb);await saveState();if(ws?.readyState===1)ws.send(JSON.stringify({type:'storage-advertise',enabled:storageEnabled,nodeId:nodeServiceId,capacityMb:nodeCapacityMb}));updateStorageText()}


async function finishExistingSetup(){
 const name=$('#newName').value.trim(),freeName=$('#newFreeName').value.trim(),secretNumber=$('#newSecretNumber').value.trim(),secretNumber2=$('#newSecretNumber2').value.trim(),pin=$('#newPin').value.trim(),pin2=$('#newPin2').value.trim();
 if(!name)throw new Error(currentLang==='vi'?'Nhập tên hiển thị.':'Enter a display name.');if(pin!==pin2||!validPin(pin))throw new Error(currentLang==='vi'?'PIN phải gồm 4–6 số và hai lần nhập phải giống nhau.':'PIN must be 4–6 digits and match.');if(secretNumber!==secretNumber2||!validSecretNumber(secretNumber))throw new Error(currentLang==='vi'?'10-digit Secret phải đúng 10 số và hai lần nhập phải giống nhau.':'10-digit Secret must be exactly 10 digits and match.');
 if(!me)me=await createIdentity();profile={displayName:name,createdAt:Date.now()};await setKV('profile',profile);contacts=await getKV('contacts')||{};chats=await getKV('chats')||{};const rec=await saveNewAccountKit(pin);const easy=await registerEasyRecovery(freeName,secretNumber,pin);$('#createdName').textContent=name;$('#createdShort').textContent=me.shortId;$('#createdQr').src=`/api/qr?text=${encodeURIComponent(inviteLink())}`;$('#createdFreeName').value=easy.name;$('#createdSecretNumber').value=secretNumber;$('#createdRecoveryAddress').value=rec.address;$('#createdRecoverySecret').value=compactSecret(rec.secret);showStep('createdStep')
}
async function restoreAccountFromKit(){
 const easyName=$('#restoreFreeName')?.value.trim()||'',secretNumber=$('#restoreSecretNumber')?.value.trim()||'',address=$('#restoreAddress')?.value.trim().toUpperCase()||'',secret=$('#restoreSecret')?.value.trim()||'',legacy=$('#restoreKitInput')?.value.trim()||'',pin=$('#restorePin').value.trim(),progress=$('#restoreProgress'),btn=$('#restoreAccount');if(btn)btn.disabled=true;
 try{progress.textContent=currentLang==='vi'?'Đang khôi phục danh tính…':'Restoring identity…';let state,sec,addr,easyFreeName='';
  if(easyName||secretNumber){const r=await restoreEasyRecovery(easyName,secretNumber,pin);state=r.state;sec=r.secret;addr=r.address;easyFreeName=r.easyFreeName}
  else if(address&&secret){const r=await decryptRecoveryCapsule(address,secret,pin);state=r.state;sec=r.secret;addr=address}
  else if(legacy){const r=await decryptAccountRecoveryKit(legacy,pin);state=r.state;sec=r.secret;const cap=await buildRecoveryCapsule(pin,sec.slice(0,20));await uploadRecoveryCapsule(cap.capsule);addr=cap.address;sec=cap.secret}
  else throw new Error(currentLang==='vi'?'Nhập FREE Name + 10-digit Secret + PIN.':'Enter FREE Name + 10-digit Secret + PIN.');
  const restoredProfile=state.profile||{displayName:'FREE'};const isCompact=state.format==='FREE-ACCOUNT-3';const restoredContacts=isCompact?{}:(state.contacts||{}),restoredChats=isCompact?{}:(state.chats||{}),restoredBlocked=state.blockedIds||{};
  await setKV('identity',state.identity);await setKV('profile',restoredProfile);await setKV('contacts',restoredContacts);await setKV('chats',restoredChats);await setKV('blockedIds',restoredBlocked);await setKV('archivedMsgIds',[]);await setKV('recoveryAddress',addr);await setKV('recoverySecret',compactSecret(sec));await setKV('accountRecoveryKit','');if(easyFreeName)await setKV('easyFreeName',easyFreeName);
  me=wrapIdentity(state.identity);profile=restoredProfile;contacts=restoredContacts;chats=restoredChats;blockedIds=restoredBlocked;archivedMsgIds=new Set();selectedId=null;vaultHydrated=false;
  progress.textContent=currentLang==='vi'?`Đã khôi phục ${me.shortId}. Đang kết nối và tải lịch sử mã hóa…`:`Restored ${me.shortId}. Connecting and loading encrypted history…`;$('#onboarding').hidden=true;$('#appShell').hidden=false;renderIdentity();renderContacts();renderChat();await connect();
 }finally{if(btn)btn.disabled=false}
}
async function refreshChain(){try{const r=await fetch('/api/chain',{cache:'no-store'});if(!r.ok)return;const c=await r.json();const h=$('#chainHeight'),fa=$('#founderAddress'),fb=$('#founderBalance'),gh=$('#genesisHash'),lh=$('#latestBlockHash'),ne=$('#chainNextEpoch');if(h)h.textContent=String(c.height??0);if(fa)fa.textContent=c.addresses?.founder||'—';if(fb)fb.textContent=`${Number(c.balances?.founder||0).toFixed(6)} FREE`;if(gh)gh.textContent=c.genesisHash||'—';if(lh)lh.textContent=c.latestBlockHash||'—';if(ne){const secs=Math.max(0,Math.ceil((Number(c.nextEpochAt||0)-Date.now())/1000));ne.textContent=`Testnet · reward epoch tiếp theo ~ ${secs}s`}}catch(e){console.warn('chain status',e)}}
function bootReady(){const b=$('#bootFallback');if(b)b.hidden=true}
function bootError(e){const b=$('#bootFallback');if(!b)return;b.classList.add('error');const span=b.querySelector('span'),small=b.querySelector('small');if(span)span.textContent=`FREE-034 không khởi động được: ${e?.message||e}`;if(small)small.textContent='Không xóa dữ liệu trình duyệt. Hãy chụp màn hình lỗi này để chẩn đoán.'}

async function init(){
 currentLang=localStorage.getItem('free-lang')||((navigator.language||'').toLowerCase().startsWith('vi')?'vi':'en');setLanguage(currentLang);db=await openDB();
 const raw=await getKV('identity');profile=await getKV('profile');contacts=await getKV('contacts')||{};chats=await getKV('chats')||{};blockedIds=await getKV('blockedIds')||{};archivedMsgIds=new Set(await getKV('archivedMsgIds')||[]);storageEnabled=!!(await getKV('storageEnabled'));readReceiptsEnabled=(await getKV('readReceiptsEnabled'))!==false;appLockEnabled=!!(await getKV('appLockEnabled'));nodeServiceId=await getKV('nodeServiceId');deviceId=await getKV('deviceId');if(!deviceId){deviceId='DEV-'+[...crypto.getRandomValues(new Uint8Array(10))].map(x=>x.toString(16).padStart(2,'0')).join('').toUpperCase();await setKV('deviceId',deviceId)};if(!nodeServiceId){nodeServiceId=[...crypto.getRandomValues(new Uint8Array(24))].map(x=>x.toString(16).padStart(2,'0')).join('');await setKV('nodeServiceId',nodeServiceId)}nodeCapacityMb=Number(await getKV('nodeCapacityMb'))||1024;$('#nodeServiceId').textContent=nodeServiceId;$('#nodeCapacity').value=String(nodeCapacityMb);$('#storageToggle').checked=storageEnabled;$('#readReceiptsToggle').checked=readReceiptsEnabled;$('#appLockToggle').checked=appLockEnabled;updateStorageText();renderDeviceList();
 if(raw?.cryptoSuite===CRYPTO_SUITE){me=wrapIdentity(raw);await restoreLocalSafetySnapshot();if(!profile){$('#onboarding').hidden=false;showStep('createStep');$('#newName').value='';}else{const kit=await getKV('accountRecoveryKit');if(kit)$('#accountRecoveryKit').value=kit;if(appLockEnabled)await lockApp();else{isUnlocked=true;showApp()}}}
 else{$('#onboarding').hidden=false;showStep('welcomeStep')}
 const hash=location.hash;if(me&&profile&&hash.startsWith('#freeid=')){try{await addFromInvite(location.href);history.replaceState(null,'',location.pathname)}catch(e){alert(e.message)}}
 const vk=await getKV('lastRecoveryKit');if(vk)$('#recoveryKit').value=vk;await refreshChain();setInterval(refreshChain,5000);bootReady();
}

