$('#changePinBtn').onclick=async()=>{try{const oldPin=$('#oldPin').value.trim(),p1=$('#changePin1').value.trim(),p2=$('#changePin2').value.trim(),easyNumber=$('#changeEasySecret')?.value.trim()||'',addr=await getKV('recoveryAddress'),secret=await getKV('recoverySecret'),easyName=await getKV('easyFreeName');if(p1!==p2||!validPin(p1))throw new Error('Invalid new PIN');if(easyName&&!validSecretNumber(easyNumber))throw new Error(currentLang==='vi'?'Nhập 10-digit Secret để cập nhật Easy Recovery cùng PIN mới.':'Enter your 10-digit Secret to update Easy Recovery with the new PIN.');await decryptRecoveryCapsule(addr,secret,oldPin);const r=await buildRecoveryCapsule(p1,unbase32(secret));await uploadRecoveryCapsule(r.capsule);if(easyName)await registerEasyRecovery(easyName,easyNumber,p1);$('#oldPin').value=$('#changePin1').value=$('#changePin2').value='';if($('#changeEasySecret'))$('#changeEasySecret').value='';alert(currentLang==='vi'?'Đã đổi PIN và cập nhật Easy Recovery.':'PIN and Easy Recovery updated.')}catch(e){alert(e.message)}};
function openSecurePinModal(mode='verify'){return new Promise(resolve=>{const m=$('#securePinModal'),inp=$('#securePinInput'),wrap=$('#securePinConfirmWrap'),confirmInp=$('#securePinConfirm'),err=$('#securePinError'),migrate=mode==='migrate';$('#securePinTitle').textContent=currentLang==='vi'?(migrate?'Nâng cấp Recovery':'Xác minh PIN'):(migrate?'Upgrade Recovery':'Verify PIN');$('#securePinLead').textContent=currentLang==='vi'?(migrate?'Tài khoản này được tạo trước Compact Recovery. Hãy nhập PIN của bạn hai lần để tạo Recovery Address và Recovery Secret mới.':'Nhập PIN để cập nhật bản sao lưu mã hóa.'):(migrate?'This account predates Compact Recovery. Enter your PIN twice to create a new Recovery Address and Recovery Secret.':'Enter your PIN to update the encrypted backup.');$('#securePinLabel').textContent=currentLang==='vi'?'PIN':'PIN';$('#securePinConfirmLabel').textContent=currentLang==='vi'?'Nhập lại PIN':'Confirm PIN';$('#securePinCancel').textContent=currentLang==='vi'?'Hủy':'Cancel';$('#securePinSubmit').textContent=currentLang==='vi'?'Tiếp tục':'Continue';wrap.hidden=!migrate;inp.value='';confirmInp.value='';err.textContent='';m.hidden=false;setTimeout(()=>inp.focus(),0);const close=v=>{m.hidden=true;$('#securePinSubmit').onclick=null;$('#securePinCancel').onclick=null;resolve(v)};$('#securePinCancel').onclick=()=>close(null);$('#securePinSubmit').onclick=()=>{const pin=inp.value.trim();if(!validPin(pin)){err.textContent=currentLang==='vi'?'PIN phải gồm 4–6 chữ số.':'PIN must contain 4–6 digits.';return}if(migrate&&pin!==confirmInp.value.trim()){err.textContent=currentLang==='vi'?'Hai lần nhập PIN không khớp.':'PIN entries do not match.';return}close(pin)}})}
async function refreshEncryptedBackup(){const addr=await getKV('recoveryAddress'),secretText=await getKV('recoverySecret'),legacy=await getKV('accountRecoveryKit');const hasCompact=!!(addr&&secretText);const pin=await openSecurePinModal(hasCompact||legacy?'verify':'migrate');if(!pin)return;let secret;if(hasCompact){await decryptRecoveryCapsule(addr,secretText,pin);secret=unbase32(secretText)}else if(legacy){const verified=await decryptAccountRecoveryKit(legacy,pin);if(verified.state?.identity?.id&&verified.state.identity.id!==me.id)throw new Error(currentLang==='vi'?'Recovery Kit cũ không thuộc FREE ID hiện tại.':'Legacy Recovery Kit does not belong to this FREE ID.');secret=verified.secret}else{secret=crypto.getRandomValues(new Uint8Array(20))}const r=await buildRecoveryCapsule(pin,secret);await uploadRecoveryCapsule(r.capsule);const compact=compactSecret(r.secret);await setKV('recoveryAddress',r.address);await setKV('recoverySecret',compact);await setKV('accountRecoveryKit','');$('#accountRecoveryAddress').value=r.address;$('#accountRecoverySecret').value=compact;$('#accountRecoverySecret').type='password';updateRecoverySecretToggle();alert(currentLang==='vi'?'Đã tạo/cập nhật Recovery an toàn. Hãy lưu Recovery Card trước khi thử khôi phục trên thiết bị khác.':'Secure Recovery created/updated. Save the Recovery Card before testing restore on another device.')}
